def stride_ways(n, strides):
    mod = 1_000_000_007
    m = max(strides)
    step = [[0] * m for _ in range(m)]
    for s in strides:
        step[0][s - 1] = 1
    for r in range(1, m):
        step[r][r - 1] = 1

    def mul(A, B):
        C = []
        for row in A:
            out = [0] * m
            for t, a in enumerate(row):
                if a:
                    for j, b in enumerate(B[t]):
                        out[j] += a * b
            C.append([x % mod for x in out])
        return C

    result = [[int(i == j) for j in range(m)] for i in range(m)]
    while n:
        if n & 1:
            result = mul(result, step)
        step = mul(step, step)
        n >>= 1
    return result[0][0]

